def conv2d(img, k):
    n, m = len(img), len(img[0])
    a, b = len(k), len(k[0])
    out = []
    for i in range(n - a + 1):
        row = []
        for j in range(m - b + 1):
            s = 0
            for u in range(a):
                for v in range(b):
                    s += img[i + u][j + v] * k[u][v]
            row.append(s)
        out.append(row)
    return out

import numpy as np

def out_size(n, k, pad=0, stride=1):
    return (n + 2 * pad - k) // stride + 1

def conv2d_np(X, K, pad=0, stride=1):
    Xp = np.pad(X, pad)
    k = K.shape[0]
    o = out_size(X.shape[0], k, pad, stride)
    Y = np.zeros((o, o))
    for i in range(o):
        for j in range(o):
            Y[i, j] = (Xp[i*stride:i*stride+k, j*stride:j*stride+k] * K).sum()
    return Y
